    p("68:36","what-for-you",[("size",2),(" ne [oluyor?]",1)],"Ma lakum asks what is with you before the how-do-you-judge challenge. Expose the question and addressee separately; the support predicate is explanatory.")
    d("68:36:1","Restore the interrogative contribution instead of a duplicated possession question.")
    d("68:39:3 68:41:3","Individually retain the lexical nouns yeminleriniz and ortakları in their respective possession/availability questions. Ayman means oaths and shurakaa partners; no additional claim that God actually granted the supposed oaths or partners is made.",True)
    p("68:42","prostration-destination",[("secde",7),("ye",6)],"Ila al-sujud marks the destination of the summons. Expose the dative and remove the copied stray semicolon.")
