    d("90:15:2","Restore the kinship qualification while leaving the orphan object intact.")
    p("90:16","destitution-state",[("sefalet",4),(" içinde olan",3)],"Dha matrabatin describes extreme destitution, idiomatically sefalet içinde olan. Expose the possessed state relation rather than an unexplained copy of hiçbir şeyi olmayan; this is a contextual poverty gloss, not literal ownership of soil.")
    d("90:16:3","Restore the destitution-state relation of the needy person.")
    for ay,stem,ending in [("91:2","onu izle","diğinde"),("91:3","onu [güneşi] ortaya çıkar","dığında"),("91:4","onu ört","tüğünde"),("93:2","sakinleş","tiğinde")]:
        p(ay,"when-clause",[(stem,3),(ending,2)],"Idha introduces when the following event occurs in the oath. Restore temporal subordination instead of a mere adjective; the inherited lexical/pronominal reading is retained, with supplied referents bracketed.")
